\begin{lemma}
\label{lemma-rank}
\begin{slogan}
The rank of a finite free module is well defined.
\end{slogan}
Let $R$ be a nonzero ring. Let $n, m \geq 0$ be integers.
If $R^{\oplus n}$ is isomorphic to $R^{\oplus m}$ as
$R$-modules, then $n = m$.
\end{lemma}

\begin{proof}
Immediate from Lemma \ref{lemma-map-cannot-be-injective}.
\end{proof}

